/* prog44_miller_rabin.c
 * Re‑implementation of the original obfuscated binary.
 * Behaviour:
 *   - prints NO_INPUT   if no argument is supplied
 *   - prints BAD_INPUT  if the argument is not a valid decimal integer
 *   - prints OUT_OF_RANGE if the integer is larger than 0xBFA17DC6
 *   - prints PRIME / NOT_PRIME according to a deterministic Miller‑Rabin
 *     test with bases {2,3,5,7,11,13}
 *
 * The program follows the exact output strings used by the original
 * binary (including case) and terminates with exit status 0.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>
#include <string.h>
#include <errno.h>

/* Upper bound used by the original program */
#define MAX_VALUE 0xBFA17DC6ULL

/* Deterministic Miller–Rabin bases for the range up to MAX_VALUE */
static const uint64_t bases[] = {2, 3, 5, 7, 11, 13};

/* (a * b) % mod using 128‑bit intermediate to avoid overflow */
static uint64_t mul_mod(uint64_t a, uint64_t b, uint64_t mod)
{
    __uint128_t res = ( __uint128_t ) a * b;
    return (uint64_t)(res % mod);
}

/* (base ^ exp) % mod – binary exponentiation */
static uint64_t pow_mod(uint64_t base, uint64_t exp, uint64_t mod)
{
    uint64_t result = 1 % mod;
    base %= mod;
    while (exp) {
        if (exp & 1)
            result = mul_mod(result, base, mod);
        base = mul_mod(base, base, mod);
        exp >>= 1;
    }
    return result;
}

/* Miller–Rabin test for a single base.
 * Returns 1 if n passes the test for this base, 0 otherwise. */
static int miller_rabin_one(uint64_t n, uint64_t a)
{
    if (a % n == 0)               /* base equal to n → trivially passes */
        return 1;

    /* write n‑1 as d·2^s with d odd */
    uint64_t d = n - 1;
    unsigned int s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        ++s;
    }

    uint64_t x = pow_mod(a, d, n);
    if (x == 1 || x == n - 1)
        return 1;

    for (unsigned int r = 1; r < s; ++r) {
        x = mul_mod(x, x, n);
        if (x == n - 1)
            return 1;
    }
    return 0;   /* composite */
}

/* Full deterministic Miller–Rabin for the required range */
static int is_prime(uint64_t n)
{
    if (n < 2)
        return 0;
    if (n == 2 || n == 3)
        return 1;
    if ((n & 1) == 0)          /* even numbers > 2 are composite */
        return 0;

    for (size_t i = 0; i < sizeof(bases)/sizeof(bases[0]); ++i) {
        uint64_t a = bases[i];
        if (a >= n)            /* skip bases not smaller than n */
            continue;
        if (!miller_rabin_one(n, a))
            return 0;          /* composite */
    }
    return 1;                  /* passed all bases → prime */
}

/* Checks whether the whole string consists of decimal digits.
 * Returns 1 on success, 0 otherwise. */
static int is_decimal_string(const char *s)
{
    if (*s == '\0')
        return 0;
    while (*s) {
        if (*s < '0' || *s > '9')
            return 0;
        ++s;
    }
    return 1;
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* Verify that the argument is a pure decimal integer */
    if (!is_decimal_string(argv[1])) {
        puts("BAD_INPUT");
        return 0;
    }

    errno = 0;
    char *endptr = NULL;
    uint64_t n = strtoull(argv[1], &endptr, 10);

    /* strtoull should have consumed the whole string; otherwise BAD_INPUT */
    if (errno != 0 || endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (n > MAX_VALUE) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    if (is_prime(n))
        puts("PRIME");
    else
        puts("NOT_PRIME");

    return 0;
}
